class Solution {
public:
    int slidingPuzzle(vector<vector<int>>& board) {
        string start;
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 3; ++j)
                start.push_back(char('0' + board[i][j]));
        const string target = "123450";
        // For each index of '0' (0..5), list of indices it can swap with on a 2x3 board.
        const vector<vector<int>> adj = {
            {1, 3},        // 0
            {0, 2, 4},     // 1
            {1, 5},        // 2
            {0, 4},        // 3
            {1, 3, 5},     // 4
            {2, 4}         // 5
        };
        unordered_map<string, int> dist;
        queue<string> q;
        q.push(start);
        dist[start] = 0;
        while (!q.empty()) {
            string cur = q.front();
            q.pop();
            if (cur == target) return dist[cur];
            int pos = (int)cur.find('0');
            for (int np : adj[pos]) {
                string nxt = cur;
                swap(nxt[pos], nxt[np]);
                if (!dist.count(nxt)) {
                    dist[nxt] = dist[cur] + 1;
                    q.push(nxt);
                }
            }
        }
        return -1;
    }
};
